public sealed class LruCache {
    readonly int[] keys, vals, prev, next;   // ячейка 0 — страж
    readonly Dictionary<int, int> slot;      // key → номер ячейки
    int used;                                // выдано ячеек: 1..capacity

    public LruCache(int capacity) {
        int n = capacity + 1;
        keys = new int[n]; vals = new int[n]; prev = new int[n]; next = new int[n];
        slot = new Dictionary<int, int>(capacity);
    }

    void Unlink(int i) { next[prev[i]] = next[i]; prev[next[i]] = prev[i]; }
    void PushFront(int i) { prev[i] = 0; next[i] = next[0]; prev[next[0]] = i; next[0] = i; }

    public int Get(int key) {
        if (!slot.TryGetValue(key, out int i)) return -1;
        Unlink(i); PushFront(i);
        return vals[i];
    }

    public void Put(int key, int value) {
        if (slot.TryGetValue(key, out int i)) Unlink(i);
        else {
            if (used < keys.Length - 1) i = ++used;
            else { i = prev[0]; Unlink(i); slot.Remove(keys[i]); }   // ячейка хвоста — новому ключу
            keys[i] = key; slot[key] = i;
        }
        vals[i] = value; PushFront(i);
    }
}

