public void Put(string key, Texture2D tex, long size) {   // Entry — struct: key, tex, size
    if (size > budget) return;                    // тяжелее бюджета — не кэшируем
    if (map.TryGetValue(key, out var old)) Evict(old);
    map[key] = order.AddFirst(new Entry(key, tex, size));
    bytes += size;
    while (bytes > budget) Evict(order.Last);     // по памяти: может уйти несколько
}

void Evict(LinkedListNode<Entry> node) {
    order.Remove(node);
    map.Remove(node.Value.key);
    bytes -= node.Value.size;
    Release(node.Value.tex);                      // Destroy или Addressables.Release
}
